import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.DoUXNnsN.js";const p=JSON.parse('{"title":"开发工具","description":"","frontmatter":{"title":"开发工具","aliases":["常用开发工具","Visual Studio","VS Code","SSMS","Postman","Everything","快捷键","编辑器","IDE"],"tags":["工具与工程","工具"],"status":"ai-draft","sources":["https://code.visualstudio.com/docs/getstarted/keybinding","https://learn.microsoft.com/en-us/visualstudio/ide/default-keyboard-shortcuts-in-visual-studio","https://learn.microsoft.com/en-us/ssms/sql-server-management-studio-shortcuts","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":21},"headers":[],"relativePath":"50-工具与工程/开发工具.md","filePath":"50-工具与工程/开发工具.md"}'),i={name:"50-工具与工程/开发工具.md"};function r(l,t,s,c,n,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<blockquote class="callout-warn"><p>⚠ 待核对：本篇的<strong>快捷键和界面操作基于各软件的官方默认设置，没有在本机逐一操作验证</strong>（标注&quot;已验证&quot;的只有命令行部分：<code>code --version</code>、<code>code --list-extensions</code>、<code>sqlcmd</code> 连接 LocalDB）。扩展的 ID 和界面菜单名称会随版本变化，请以软件内实际显示和官方文档为准。</p></blockquote><blockquote><p>读完你应该能：知道写 C#、写 SQL、测接口、搜文件各该用什么工具；记住最值钱的十几个快捷键；会在命令行里确认这些工具装好了；挑选几个提升效率的 VS Code 扩展。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>开发工具是<strong>写代码、跑代码、查问题、管数据</strong>时用的软件：编辑器/IDE（写代码）、数据库管理工具（查数据）、接口测试工具（调接口）、搜索与对比工具（找东西）。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li>会用 Windows 基本操作，知道什么是命令行（见 <a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>、<a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a>）。</li><li>知道 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>：命令行里能直接敲 <code>code</code>、<code>git</code>，靠的是 PATH。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>同样的活儿，用对工具可能快 10 倍：在 3 万个文件里找一个类名，用文件夹搜索要几分钟，用 Everything 是瞬间；改一个变量名要改 20 处，手改易漏，用&quot;重命名&quot;一键改全；调试时逐行看变量，比到处 <code>Console.WriteLine</code> 快得多。快捷键的价值：每天少伸手摸几百次鼠标，一天能省下可观的时间，也更不容易打断思路。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="工具总览-按用途" tabindex="-1">工具总览（按用途） <a class="header-anchor" href="#工具总览-按用途" aria-label="Permalink to &quot;工具总览（按用途）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用途</th><th>推荐工具</th><th>说明</th></tr></thead><tbody><tr><td>写 C#/.NET（重型）</td><td>Visual Studio</td><td>本机已安装（目录 <code>C:\\Program Files\\Microsoft Visual Studio\\18</code> 存在）；调试、WinForms/WPF 设计器、性能分析最强</td></tr><tr><td>轻量写代码、写 Markdown、前端</td><td>VS Code</td><td>本机已安装，版本 1.138.0；插件多</td></tr><tr><td>查询 SQL Server</td><td>SSMS（SQL Server Management Studio）</td><td>本机已装 20 和 22 两个版本（目录存在）；管理数据库、看执行计划（见 <a href="/Encyclopedia/40-数据库/通用/执行计划与SQL优化">执行计划与SQL优化</a>）</td></tr><tr><td>命令行查询 SQL</td><td><code>sqlcmd</code></td><td>本机可用，可连 LocalDB</td></tr><tr><td>测 Web API</td><td>Postman</td><td>构造 HTTP 请求、保存为集合、用环境变量切换服务器地址（见 <a href="/Encyclopedia/30-.NET生态/WebAPI开发">WebAPI开发</a>、<a href="/Encyclopedia/50-工具与工程/REST-API设计">REST-API设计</a>）</td></tr><tr><td>搜文件</td><td>Everything</td><td>按文件名秒搜整台电脑；本机未检测到安装</td></tr><tr><td>版本管理</td><td>Git + Git 图形工具</td><td>本机 Git 2.54.0；VS Code 有 Git Graph 扩展（已装）</td></tr><tr><td>终端</td><td>Windows Terminal（<code>wt</code>）</td><td>本机已安装；可开 PowerShell、cmd、Git Bash 多标签</td></tr><tr><td>对比文件</td><td>VS Code 自带 diff、WinMerge、Beyond Compare</td><td>对比两个配置文件、两个版本的 SQL</td></tr><tr><td>反编译</td><td>ILSpy</td><td>看别人 DLL 里的代码（⚠ 本机未验证）</td></tr><tr><td>抓包</td><td>Wireshark</td><td>看网络上实际收发的报文（排查 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a> 通信）</td></tr></tbody></table><h3 id="在命令行里确认工具已装好-已在本机验证" tabindex="-1">在命令行里确认工具已装好（已在本机验证） <a class="header-anchor" href="#在命令行里确认工具已装好-已在本机验证" aria-label="Permalink to &quot;在命令行里确认工具已装好（已在本机验证）&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">extensions</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sqlcmd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">S </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;(localdb)\\MSSQLLocalDB&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Q </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SELECT 1 AS ok&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">W</span></span></code></pre></div><p>本机实测：<code>code --version</code> 的第一行是 <code>1.138.0</code>；<code>git --version</code> 输出 <code>git version 2.54.0.windows.1</code>；<code>sqlcmd</code> 连接 LocalDB 返回：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ok</span></span>
<span class="line"><span>--</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(1 rows affected)</span></span></code></pre></div><p><code>sqlcmd</code> 的 <code>-S</code> 是服务器名，<code>(localdb)\\MSSQLLocalDB</code> 是 LocalDB 的默认实例；<code>-Q</code> 执行一句 SQL 后退出；<code>-W</code> 去掉输出里多余的空格。<strong>本库的练习库固定在 LocalDB 里，不要连电脑上其它 SQL Server 实例去做实验。</strong></p><h3 id="快捷键速查-官方默认键位-⚠-未逐一验证" tabindex="-1">快捷键速查（官方默认键位，⚠ 未逐一验证） <a class="header-anchor" href="#快捷键速查-官方默认键位-⚠-未逐一验证" aria-label="Permalink to &quot;快捷键速查（官方默认键位，⚠ 未逐一验证）&quot;">​</a></h3><p><strong>VS Code</strong></p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl+P</code></td><td>按文件名快速打开文件</td></tr><tr><td><code>Ctrl+Shift+P</code></td><td>命令面板（几乎所有功能都能在这里搜到）</td></tr><tr><td><code>Ctrl+\`</code></td><td>打开/隐藏内置终端（<code>\`</code> 是键盘左上角数字 1 左边的反引号键）</td></tr><tr><td><code>Ctrl+/</code></td><td>注释/取消注释当前行</td></tr><tr><td><code>Alt+↑ / Alt+↓</code></td><td>上下移动当前行</td></tr><tr><td><code>Shift+Alt+↓</code></td><td>向下复制当前行</td></tr><tr><td><code>Ctrl+D</code></td><td>选中下一个相同的词（多光标改名）</td></tr><tr><td><code>F2</code></td><td>重命名符号（改所有引用）</td></tr><tr><td><code>F12</code></td><td>转到定义</td></tr><tr><td><code>Ctrl+Shift+F</code></td><td>全项目搜索</td></tr><tr><td><code>Ctrl+Shift+V</code></td><td>Markdown 预览</td></tr><tr><td><code>F5</code></td><td>开始调试</td></tr></tbody></table><p><strong>Visual Studio</strong></p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>F5</code> / <code>Ctrl+F5</code></td><td>调试运行 / 不调试直接运行</td></tr><tr><td><code>F9</code></td><td>设置/取消断点</td></tr><tr><td><code>F10</code> / <code>F11</code> / <code>Shift+F11</code></td><td>逐过程（不进函数）/ 逐语句（进入函数）/ 跳出函数</td></tr><tr><td><code>Ctrl+Shift+B</code></td><td>生成（编译）解决方案</td></tr><tr><td><code>F12</code> / <code>Shift+F12</code></td><td>转到定义 / 查找所有引用</td></tr><tr><td><code>Ctrl+.</code></td><td>快速操作与重构（补 using、生成方法、提取方法等）</td></tr><tr><td><code>Ctrl+R, Ctrl+R</code></td><td>重命名</td></tr><tr><td><code>Ctrl+K, Ctrl+C</code> / <code>Ctrl+K, Ctrl+U</code></td><td>注释 / 取消注释所选行</td></tr><tr><td><code>Ctrl+K, Ctrl+D</code></td><td>格式化整个文档</td></tr><tr><td><code>Ctrl+T</code></td><td>转到全部（按类名、文件名、成员名搜索）</td></tr></tbody></table><p><strong>SSMS</strong></p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>F5</code> 或 <code>Ctrl+E</code></td><td>执行（有选中文本就只执行选中部分，<strong>没选中则执行全部</strong>，小心！）</td></tr><tr><td><code>Ctrl+N</code></td><td>新建查询窗口</td></tr><tr><td><code>Ctrl+L</code></td><td>显示预计执行计划</td></tr><tr><td><code>Ctrl+M</code></td><td>包含实际执行计划（再执行）</td></tr><tr><td><code>Ctrl+R</code></td><td>显示/隐藏结果窗格</td></tr><tr><td><code>Ctrl+K, Ctrl+C</code> / <code>Ctrl+K, Ctrl+U</code></td><td>注释 / 取消注释</td></tr><tr><td><code>Ctrl+Shift+U</code> / <code>Ctrl+Shift+L</code></td><td>选中文字转大写 / 小写</td></tr><tr><td><code>Alt+F1</code></td><td>对选中的对象名执行 <code>sp_help</code>，查看表结构</td></tr></tbody></table><p><strong>通用</strong></p><ul><li><code>Ctrl+C/V/X/Z/Y</code>、<code>Ctrl+F</code>（查找）、<code>Ctrl+H</code>（替换）、<code>Ctrl+S</code>（保存）。</li><li><code>Win+↑/←/→</code> 窗口贴边；<code>Win+Shift+S</code> 截图。</li></ul><h3 id="everything-的搜索技巧-⚠-未在本机验证" tabindex="-1">Everything 的搜索技巧（⚠ 未在本机验证） <a class="header-anchor" href="#everything-的搜索技巧-⚠-未在本机验证" aria-label="Permalink to &quot;Everything 的搜索技巧（⚠ 未在本机验证）&quot;">​</a></h3><p>Everything 只按文件名（和路径）搜索，速度快是因为它直接读取 NTFS 文件系统的索引。常用写法：</p><ul><li>直接输入关键词，多个词用空格（同时包含）。</li><li><code>*.md</code>：通配符；<code>ext:cs;sql</code>：指定扩展名。</li><li><code>path:kb</code>：路径里含有 kb；<code>size:&gt;10mb</code>：大于 10MB。</li><li><code>dm:today</code>：今天修改过的文件。</li></ul><h3 id="postman-的基本用法-⚠-未在本机验证" tabindex="-1">Postman 的基本用法（⚠ 未在本机验证） <a class="header-anchor" href="#postman-的基本用法-⚠-未在本机验证" aria-label="Permalink to &quot;Postman 的基本用法（⚠ 未在本机验证）&quot;">​</a></h3><ol><li>新建请求（Request），选方法（GET/POST…），填 URL。</li><li>在 Headers 和 Body 里填请求头和请求体（JSON）。</li><li>点 Send，看响应状态码、响应体、耗时。</li><li>把相关请求存进 <strong>Collection（集合）</strong>，方便复用和分享。</li><li>用 <strong>Environment（环境）</strong> 存放变量，比如开发、测试、生产的服务器地址，切换环境即可不改请求；环境变量用两层花括号把变量名括起来引用。</li><li>不要把生产环境的真实令牌和密码保存进共享集合。</li></ol><h3 id="vs-code-扩展推荐" tabindex="-1">VS Code 扩展推荐 <a class="header-anchor" href="#vs-code-扩展推荐" aria-label="Permalink to &quot;VS Code 扩展推荐&quot;">​</a></h3><p>本机已安装（见 <code>code --list-extensions</code> 的输出，已验证）：</p><table tabindex="0"><thead><tr><th>扩展 ID</th><th>作用</th></tr></thead><tbody><tr><td><code>vue.volar</code></td><td>Vue 3 语言支持（见 <a href="/Encyclopedia/35-前端/Vue/Vue">Vue</a>）</td></tr><tr><td><code>dbaeumer.vscode-eslint</code></td><td>JavaScript/TypeScript 代码检查</td></tr><tr><td><code>mhutchie.git-graph</code></td><td>图形化查看 Git 提交图</td></tr><tr><td><code>streetsidesoftware.code-spell-checker</code></td><td>代码里的拼写检查（变量名拼错能提示）</td></tr><tr><td><code>ritwickdey.liveserver</code></td><td>本地静态网页一键预览</td></tr><tr><td><code>ms-ceintl.vscode-language-pack-zh-hans</code></td><td>中文界面</td></tr></tbody></table><p>另外常见的推荐（⚠ 本机未安装、ID 未验证，请在扩展市场搜索名称确认）：</p><table tabindex="0"><thead><tr><th>名称</th><th>作用</th></tr></thead><tbody><tr><td>C# Dev Kit</td><td>在 VS Code 里写 C#/.NET</td></tr><tr><td>Python</td><td>Python 语言支持、调试、运行测试</td></tr><tr><td>GitLens</td><td>每行代码是谁在什么时候改的</td></tr><tr><td>Markdown All in One</td><td>Markdown 快捷键、目录生成</td></tr></tbody></table><p>安装扩展的命令行写法是 <code>code --install-extension 扩展ID</code>。</p><h2 id="逐步例子" tabindex="-1">逐步例子 <a class="header-anchor" href="#逐步例子" aria-label="Permalink to &quot;逐步例子&quot;">​</a></h2><p><strong>例子：用三个工具配合，定位一个&quot;接口返回 500&quot;的问题</strong>（流程示意，界面细节⚠ 未验证）：</p><ol><li>在 <strong>Postman</strong> 里发请求 <code>GET /api/workorders/WO001</code>，看到状态码 500，响应体里有一句异常信息。</li><li>在 <strong>VS Code</strong>（或 Visual Studio）里按 <code>Ctrl+Shift+F</code> 搜索异常信息中的关键字，找到抛出的代码位置。</li><li>在 Visual Studio 里按 <code>F9</code> 给可疑行下断点，按 <code>F5</code> 调试运行，再用 Postman 重发一次请求，程序会停在断点处，用 <code>F10</code>、<code>F11</code> 逐行看变量（方法见 <a href="/Encyclopedia/50-工具与工程/调试与排错方法">调试与排错方法</a>）。</li><li>怀疑是 SQL 问题，在 <strong>SSMS</strong> 里新建查询（<code>Ctrl+N</code>），粘贴程序打出来的 SQL，按 <code>F5</code> 执行验证；必要时 <code>Ctrl+M</code> 打开实际执行计划看是否缺索引。</li><li>改好后，在终端里 <code>git status</code> 看改了哪些文件，提交（见 <a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a>）。</li></ol><p>整条链路里每个工具只做自己最擅长的一段。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ol><li>打开 PowerShell，运行前面的四条确认命令，把输出与上面对比。</li><li>在 VS Code 里打开一个文件夹（命令行：<code>code .</code>），练习 <code>Ctrl+P</code> 开文件、<code>Ctrl+Shift+P</code> 输入 <code>Markdown</code> 看有哪些命令。</li><li>用 <code>Ctrl+D</code> 连续选中同名变量，一次改名；再对比用 <code>F2</code> 重命名的区别。</li><li>在 SSMS 中用 LocalDB 实例（服务器名输入 <code>(localdb)\\MSSQLLocalDB</code>）新建查询，执行 <code>SELECT 1 AS ok</code>；再试选中部分文字后按 <code>F5</code> 只执行选中部分。（⚠ SSMS 的连接对话框界面未在本机验证；用 <code>sqlcmd</code> 已验证。）</li><li>在 Visual Studio 中新建一个控制台程序，练习 <code>F9</code>、<code>F5</code>、<code>F10</code>、<code>F11</code>，观察&quot;局部变量&quot;窗口。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><ul><li><strong>命令行里 <code>code</code> 找不到</strong>：VS Code 安装时没勾选&quot;添加到 PATH&quot;，需要在 PATH 里加入其 <code>bin</code> 目录，并重开终端（见 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>）。</li><li><strong>SSMS 里不选中就按 F5 执行了整个脚本</strong>：脚本里有 <code>DELETE</code>/<code>UPDATE</code> 时很危险。好习惯：危险语句先写 <code>BEGIN TRAN</code>，确认影响行数后再 <code>COMMIT</code> 或 <code>ROLLBACK</code>，并且<strong>连接前先看清当前连的是哪个服务器和哪个库</strong>（生产库别随手连；本库练习只用 LocalDB 的 <code>MiniMES_Lab</code>）。</li><li><strong>Postman 环境变量没生效</strong>：右上角没选中对应 Environment，或变量名拼错。</li><li><strong>Visual Studio 断点是空心的/不命中</strong>：代码与运行的 DLL 不一致（用了 Release 模式、没重新生成、调试的不是这个项目）。切换到 Debug、重新生成。</li><li><strong>快捷键冲突</strong>：输入法、截图软件、远程桌面占用了同样的组合键。可在软件设置里重新绑定。</li><li><strong>扩展装太多，编辑器变慢</strong>：只留常用的，工作区按项目启用不同扩展。</li><li><strong>Everything 搜不到内容</strong>：它只搜文件名，不搜文件里的文字。搜内容用 VS Code 的全项目搜索（<code>Ctrl+Shift+F</code>）。</li><li><strong>在生产机上安装开发工具</strong>：不要。生产机只放运行环境，调试在测试环境完成。</li><li><strong>编辑器自动保存/自动格式化改了一大片</strong>：团队统一格式化配置（见 <a href="/Encyclopedia/50-工具与工程/代码规范与重构">代码规范与重构</a>），首次格式化单独提交。</li></ul><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><p><strong>业务视角</strong>：现场工程师、质量工程师未必写代码，但常常要用其中几个：<strong>Everything</strong> 找图纸和文件，<strong>WinMerge/Beyond Compare</strong> 对比两版配置文件，<strong>Wireshark</strong> 配合 IT 排查设备通信，<strong>Postman</strong> 在接口联调时与开发人员对一下数据。统一工具与版本，团队沟通成本会低很多。涉及生产数据时，所有工具的访问权限都应遵守公司的信息安全规定。</p><p><strong>技术视角</strong>：</p><ul><li>个人电脑环境尽量可复现：记录装了哪些工具和版本（可用 <code>code --list-extensions</code>、<code>dotnet --list-sdks</code> 的输出存档），换电脑时少走弯路。</li><li>配置文件（如 <code>.editorconfig</code>、VS Code 的工作区设置）放进仓库共享，让团队用同样的格式化和检查规则。</li><li>学会命令行与图形工具两种方式：图形工具适合探索，命令行适合脚本化和自动化（见 <a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a>）。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>想一次性改掉文件里的 5 处变量名 <code>cnt</code>，VS Code 里有哪两种做法？ <ul><li>答案：<code>Ctrl+D</code> 逐个选中相同文字再统一输入（多光标）；或者光标放在变量上按 <code>F2</code> 做符号重命名，工具会改所有真正的引用（更安全，不会误改同名字符串）。</li></ul></li><li>SSMS 里为什么要特别注意&quot;选中文本再按 F5&quot;的行为？ <ul><li>答案：选中了就只执行选中部分，没选中则执行整个窗口的全部脚本，可能误执行危险语句。</li></ul></li><li>Visual Studio 里 <code>F10</code> 和 <code>F11</code> 的区别？ <ul><li>答案：<code>F10</code> 逐过程，一行调用当作一步，不进入函数内部；<code>F11</code> 逐语句，遇到函数调用会进入函数。</li></ul></li><li>Everything 能不能搜到&quot;包含某句话的 Word 文档&quot;？ <ul><li>答案：默认不能，它按文件名搜索；搜内容要用别的工具（如 VS Code 全项目搜索，或 Windows 搜索的内容索引）。</li></ul></li><li>怎么在命令行里确认 LocalDB 可用？ <ul><li>答案：<code>sqlcmd -S &quot;(localdb)\\MSSQLLocalDB&quot; -Q &quot;SELECT 1 AS ok&quot; -W</code>，返回 <code>ok</code> 和 <code>1</code>。</li></ul></li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工具选择：重型 .NET 开发用 Visual Studio，轻量编辑用 VS Code，SQL 用 SSMS/<code>sqlcmd</code>，接口用 Postman，搜文件用 Everything。</li><li>先学十几个高频快捷键：打开文件、命令面板、全局搜索、重命名、断点与单步。</li><li>危险操作（SSMS 执行、生产连接）要养成确认习惯。</li><li>本篇的快捷键与界面操作未逐一在本机验证，以官方文档为准。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><ul><li><a href="/Encyclopedia/50-工具与工程/调试与排错方法">调试与排错方法</a>：工具配合使用的思路。</li><li><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>：版本管理工具。</li><li><a href="/Encyclopedia/50-工具与工程/Markdown">Markdown</a>：在编辑器里写词条。</li><li><a href="/Encyclopedia/40-数据库/SQL-Server/SQL-Server">SQL-Server</a>、<a href="/Encyclopedia/40-数据库/SQL-Server/SQL-Server常用运维">SQL-Server常用运维</a>：SSMS 对应的数据库知识。</li><li><a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a>、<a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a></li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>VS Code 键盘快捷键：<a href="https://code.visualstudio.com/docs/getstarted/keybinding" target="_blank" rel="noreferrer">https://code.visualstudio.com/docs/getstarted/keybinding</a></li><li>Visual Studio 默认键盘快捷键：<a href="https://learn.microsoft.com/en-us/visualstudio/ide/default-keyboard-shortcuts-in-visual-studio" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/visualstudio/ide/default-keyboard-shortcuts-in-visual-studio</a></li><li>SSMS 键盘快捷键：<a href="https://learn.microsoft.com/en-us/ssms/sql-server-management-studio-shortcuts" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/ssms/sql-server-management-studio-shortcuts</a></li></ul>`,56)])])}const S=d(i,[["render",r]]);export{p as __pageData,S as default};
